import {seasonMeta,seasonState,PASS_PRICE} from './season.js';
import {rewardSkinInfo} from './reward-skins.js';
export const ZIRVE_PATHS={avci:{name:'Avcı',icon:'◎',color:'#f5824b',description:'Yem topla, rakip yen ve skorunu büyüt.',metrics:['food','kills','bestScore','seconds'],targets:[500,3,15000,1200]},sampiyon:{name:'Şampiyon',icon:'♛',color:'#ffda64',description:'Oda kazan, MMA’da birinci ol ve zirveye çık.',metrics:['wins','bestScore','mmaWins','seconds'],targets:[1,25000,1,1200]},klan:{name:'Klan',icon:'⚑',color:'#48d7bc',description:'Klanınla oyna, tur kazan ve birlikte ilerle.',metrics:['clanSeconds','clanWins','food','kills'],targets:[1200,1,500,3]}};
const labels={food:'yem topla',kills:'rakip yen',bestScore:'skora ulaş',seconds:'saniye oyna',wins:'tur kazan',mmaWins:'MMA turu kazan',clanSeconds:'saniye klan üyesiyken oyna',clanWins:'klan üyesiyken tur kazan'};
export function zirveState(p,now=Date.now()){const meta=seasonMeta(now);seasonState(p,now);if(p.zirveYolu?.id!==meta.id){p.zirveYolu={id:meta.id,path:null,claimed:{}}}p.zirveTitles??=[];return p.zirveYolu}
export function chooseZirvePath(p,path,now=Date.now()){if(!Object.hasOwn(ZIRVE_PATHS,path))throw Error('Geçerli bir yol seç');const s=zirveState(p,now);if(s.path&&s.path!==path)throw Error('Sezon boyunca yalnızca bir yol seçebilirsin');s.path=path;return s}
export function activateZirve(p,now=Date.now()){const s=seasonState(p,now);if(s.paid)throw Error('Bu sezonun bileti zaten açık');if(p.gold<PASS_PRICE)throw Error('Zirve Yolu için 5.000.000 Gold gerekli');p.gold-=PASS_PRICE;s.paid=true;zirveState(p,now)}
export function zirveMissions(path){const p=ZIRVE_PATHS[path];if(!p)return [];return Array.from({length:20},(_,i)=>{const metric=p.metrics[i%4],target=p.targets[i%4]*(Math.floor(i/4)+1);return {level:i+1,metric,target,label:target.toLocaleString('tr-TR')+' '+labels[metric]}})}
export function zirveProgress(p,now=Date.now()){const s=zirveState(p,now),stats=seasonState(p,now).stats;let level=0;for(const mission of zirveMissions(s.path)){if((stats[mission.metric]||0)<mission.target)break;level=mission.level}return level}
export function zirveRewards(path,level,now=Date.now()){if(!Object.hasOwn(ZIRVE_PATHS,path)||!Number.isInteger(level)||level<1||level>20)return [];if(level%5)return [{id:'gold',kind:'gold',amount:level*2500,name:(level*2500).toLocaleString('tr-TR')+' Gold'}];const skin='zirve-'+seasonMeta(now).number+'-'+path+'-'+level;return [{id:'gold',kind:'gold',amount:level*10000,name:(level*10000).toLocaleString('tr-TR')+' Gold'},{id:'premium',kind:'premium',days:level/5,name:level/5+' gün Premium'},{id:'skin',kind:'skin',skin,name:rewardSkinInfo(skin).name+' skini'}]}
export function claimZirve(p,level,choice,now=Date.now()){
 const s=zirveState(p,now),meta=seasonMeta(now);if(!s.path||!seasonState(p,now).paid)throw Error('Önce yolunu seç ve sezon biletini aç');if(!Number.isInteger(level)||level<1||level>zirveProgress(p,now)||s.claimed[level])throw Error('Kademe kilitli veya ödül alındı');const reward=zirveRewards(s.path,level,now).find(r=>r.id===choice);if(!reward)throw Error('Geçerli ödül seç');
 if(reward.kind==='gold')p.gold+=reward.amount;else if(reward.kind==='premium')p.premiumUntil=Math.max(now,p.premiumUntil||0)+reward.days*86400000;else{const info=rewardSkinInfo(reward.skin);p.cosmetics[reward.skin]={id:reward.skin,type:'skin',name:reward.name,color:info.color,season:meta.id};if(!p.inventory.includes(reward.skin))p.inventory.push(reward.skin)}s.claimed[level]=choice;
 if(level===20){const id='zirve-title-'+meta.number+'-'+s.path,title=meta.number+'. Sezon '+({avci:'Avcısı',sampiyon:'Şampiyonu',klan:'Klan Öncüsü'})[s.path];p.cosmetics[id]={id,type:'title',name:title,color:ZIRVE_PATHS[s.path].color,season:meta.id};if(!p.inventory.includes(id))p.inventory.push(id);if(!p.zirveTitles.some(t=>t.id===id))p.zirveTitles.push({id,name:title,season:meta.number,path:s.path})}
 return reward;
}
export function zirveEntry(p){return p?.zirveTitles?.at(-1)?.name||''}
